import time,json,statistics
import rclpy
from rclpy.node import Node
from rclpy.parameter import Parameter
from rclpy.qos import QoSProfile
from tf2_msgs.msg import TFMessage
from std_msgs.msg import String
rclpy.init();n=Node("p3b5_read_only_tf_age_probe",parameter_overrides=[Parameter("use_sim_time",value=True)])
samples={"raw":[],"gateway":[]}
def tf(m):
    now=n.get_clock().now().nanoseconds/1e9
    for t in m.transforms:
        if t.header.frame_id.endswith("map") and t.child_frame_id.endswith("odom"):
            samples["raw"].append(now-t.header.stamp.sec-t.header.stamp.nanosec/1e9+.2)
def ledger(m):
    e=json.loads(m.data)
    if e["event"]=="enqueue" and e.get("message_type")=="frame_state" and e.get("sender")=="tb2":
        samples["gateway"].append(e["enqueue_time"]-e["source_time"])
n.create_subscription(TFMessage,"/tb2/tf",tf,QoSProfile(depth=1))
n.create_subscription(String,"/gateway/message_events",ledger,QoSProfile(depth=10))
end=time.monotonic()+25
while time.monotonic()<end:rclpy.spin_once(n,timeout_sec=.1)
out={k:{"n":len(v),"min":min(v) if v else None,"median":statistics.median(v) if v else None,"p95":sorted(v)[int(.95*(len(v)-1))] if v else None} for k,v in samples.items()}
print(json.dumps(out));n.destroy_node();rclpy.shutdown()
